import './styles.css';
import { useState } from 'react';

interface TouchPoint {
  id: string;
  time: string;
  title: string;
  icon: string;
  aiExamples: string[];
  category: 'visible' | 'hidden';
}

const touchpoints: TouchPoint[] = [
  {
    id: 'morning',
    time: '7:00 AM',
    title: 'Morning Routine',
    icon: '🌅',
    aiExamples: [
      'Smart alarm learns your sleep cycles',
      'Weather app predicts conditions',
      'News feed curates stories for you',
      'Coffee maker with scheduling',
    ],
    category: 'visible',
  },
  {
    id: 'commute',
    time: '8:30 AM',
    title: 'Commute',
    icon: '🚗',
    aiExamples: [
      'Maps app predicts traffic patterns',
      'Rideshare matches you with drivers',
      'Music streaming picks next song',
      'Podcast app suggests episodes',
    ],
    category: 'visible',
  },
  {
    id: 'work',
    time: '9:00 AM',
    title: 'Work/Email',
    icon: '💼',
    aiExamples: [
      'Spam filter sorts your inbox',
      'Smart compose suggests replies',
      'Calendar suggests meeting times',
      'Search ranks internal documents',
    ],
    category: 'hidden',
  },
  {
    id: 'lunch',
    time: '12:30 PM',
    title: 'Lunch Break',
    icon: '🍕',
    aiExamples: [
      'Restaurant app recommends places',
      'Payment detects fraud patterns',
      'Social media ranks your feed',
      'Photo app auto-enhances images',
    ],
    category: 'hidden',
  },
  {
    id: 'afternoon',
    time: '3:00 PM',
    title: 'Afternoon Tasks',
    icon: '📝',
    aiExamples: [
      'Keyboard predicts your words',
      'Spellcheck fixes errors',
      'Video calls blur background',
      'Voice assistant sets reminders',
    ],
    category: 'hidden',
  },
  {
    id: 'evening',
    time: '7:00 PM',
    title: 'Evening Relaxation',
    icon: '🎬',
    aiExamples: [
      'Netflix recommends what to watch',
      'Spotify builds your playlist',
      'Smart TV suggests content',
      'Thermostat adjusts temperature',
    ],
    category: 'visible',
  },
  {
    id: 'shopping',
    time: '8:30 PM',
    title: 'Online Shopping',
    icon: '🛒',
    aiExamples: [
      'Product recommendations appear',
      'Prices adjust dynamically',
      'Chatbot answers questions',
      'Review summaries generated',
    ],
    category: 'hidden',
  },
  {
    id: 'night',
    time: '10:00 PM',
    title: 'Bedtime',
    icon: '🌙',
    aiExamples: [
      'Smart home locks doors',
      'Security cameras detect motion',
      'Sleep tracker monitors rest',
      'Phone suggests wind-down mode',
    ],
    category: 'visible',
  },
];

interface DiscoveredItem {
  touchpointId: string;
  example: string;
}

function TouchPointCard({
  point,
  discovered,
  onDiscover,
  isActive,
  onSelect,
}: {
  point: TouchPoint;
  discovered: string[];
  onDiscover: (example: string) => void;
  isActive: boolean;
  onSelect: () => void;
}) {
  return (
    <div
      className={`touchpoint-card ${isActive ? 'active' : ''}`}
      onClick={onSelect}
    >
      <div className="card-header">
        <span className="time-badge">{point.time}</span>
        <span className="icon">{point.icon}</span>
      </div>
      <h3>{point.title}</h3>
      <div className="discovery-count">
        {discovered.length}/{point.aiExamples.length} discovered
      </div>
      <div className="progress-bar">
        <div
          className="progress-fill"
          style={{ width: `${(discovered.length / point.aiExamples.length) * 100}%` }}
        />
      </div>
    </div>
  );
}

function DetailPanel({
  point,
  discovered,
  onDiscover,
}: {
  point: TouchPoint;
  discovered: string[];
  onDiscover: (example: string) => void;
}) {
  return (
    <div className="detail-panel">
      <div className="panel-header">
        <span className="big-icon">{point.icon}</span>
        <div>
          <h2>{point.title}</h2>
          <span className="panel-time">{point.time}</span>
        </div>
      </div>

      <p className="panel-desc">
        Click each card to reveal AI working in the background.
        <span className={`category-tag ${point.category}`}>
          {point.category === 'visible' ? '👁 Often visible' : '🔍 Usually hidden'}
        </span>
      </p>

      <div className="examples-grid">
        {point.aiExamples.map((example, i) => {
          const isDiscovered = discovered.includes(example);
          return (
            <div
              key={i}
              className={`example-card ${isDiscovered ? 'discovered' : ''}`}
              onClick={() => !isDiscovered && onDiscover(example)}
            >
              {isDiscovered ? (
                <>
                  <span className="check">✓</span>
                  <span className="example-text">{example}</span>
                </>
              ) : (
                <>
                  <span className="question">?</span>
                  <span className="example-text">Tap to reveal</span>
                </>
              )}
            </div>
          );
        })}      </div>
    </div>
  );
}

function ReflectionPanel({ totalDiscovered, totalPossible }: { totalDiscovered: number; totalPossible: number }) {
  const percentage = Math.round((totalDiscovered / totalPossible) * 100);

  return (
    <div className="reflection-panel">
      <h3>Your AI Awareness Map</h3>
      <div className="score-display">
        <div className="score-circle">
          <span className="score-number">{totalDiscovered}</span>
          <span className="score-label">of {totalPossible}</span>
        </div>
        <p className="score-message">
          {percentage < 30 && "Keep exploring! There's more AI than meets the eye."}
          {percentage >= 30 && percentage < 70 && "Good progress! You're seeing patterns now."}
          {percentage >= 70 && "Excellent awareness! You've mapped most of your AI interactions."}
        </p>
      </div>

      <div className="reflection-questions">
        <h4>Reflect</h4>
        <ul>
          <li>Which AI surprised you?</li>
          <li>Which AI do you find most helpful?</li>
          <li>Any AI you'd rather not have?</li>
        </ul>
      </div>
    </div>
  );
}

export default function App() {
  const [activePoint, setActivePoint] = useState<string>(touchpoints[0].id);
  const [discoveries, setDiscoveries] = useState<Record<string, string[]>>(
    Object.fromEntries(touchpoints.map(t => [t.id, []]))
  );

  const handleDiscover = (pointId: string, example: string) => {
    setDiscoveries(prev => ({
      ...prev,
      [pointId]: [...prev[pointId], example]
    }));
  };

  const currentPoint = touchpoints.find(t => t.id === activePoint)!;
  const totalDiscovered = Object.values(discoveries).flat().length;
  const totalPossible = touchpoints.reduce((sum, t) => sum + t.aiExamples.length, 0);

  return (
    <div className="app">
      <div className="header">
        <h1>AI Touchpoints Map</h1>
        <p>Discover all the AI woven into your typical day</p>
      </div>

      <div className="timeline">
        {touchpoints.map(point => (
          <TouchPointCard
            key={point.id}
            point={point}
            discovered={discoveries[point.id]}
            onDiscover={(ex) => handleDiscover(point.id, ex)}
            isActive={activePoint === point.id}
            onSelect={() => setActivePoint(point.id)}
          />
        ))}
      </div>

      <div className="main-content">
        <DetailPanel
          point={currentPoint}
          discovered={discoveries[currentPoint.id]}
          onDiscover={(ex) => handleDiscover(currentPoint.id, ex)}
        />
        <ReflectionPanel totalDiscovered={totalDiscovered} totalPossible={totalPossible} />
      </div>

      <div className="insight-box">
        <strong>Key insight:</strong> Most AI you interact with is invisible—spam filters, predictive text, content ranking. The more visible AI (voice assistants, smart devices) is just the tip of the iceberg.
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1000px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
}

.header p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.95rem;
}

.timeline {
  display: flex;
  gap: 0.5rem;
  overflow-x: auto;
  padding: 0.5rem 0;
  margin-bottom: 1.5rem;
  -webkit-overflow-scrolling: touch;
}

.touchpoint-card {
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.15);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem;
  width: 110px;
  cursor: pointer;
  transition: all 0.2s;
}

.touchpoint-card:hover {
  background: rgba(255, 255, 255, 0.25);
}

.touchpoint-card.active {
  background: white;
  border-color: #4f46e5;
}

.touchpoint-card.active h3,
.touchpoint-card.active .discovery-count {
  color: #1f2937;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.time-badge {
  font-size: 0.6rem;
  background: rgba(0, 0, 0, 0.2);
  padding: 0.15rem 0.35rem;
  border-radius: 0.25rem;
  color: white;
}

.touchpoint-card.active .time-badge {
  background: #4f46e5;
}

.icon {
  font-size: 1.25rem;
}

.touchpoint-card h3 {
  font-size: 0.75rem;
  color: white;
  margin-bottom: 0.25rem;
  line-height: 1.2;
}

.discovery-count {
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 0.35rem;
}

.progress-bar {
  height: 4px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 2px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: #22c55e;
  transition: width 0.3s ease;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 1rem;
  margin-bottom: 1rem;
}

@media (max-width: 700px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.detail-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.panel-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.big-icon {
  font-size: 2.5rem;
}

.panel-header h2 {
  font-size: 1.25rem;
  color: #1f2937;
}

.panel-time {
  font-size: 0.85rem;
  color: #6b7280;
}

.panel-desc {
  font-size: 0.9rem;
  color: #4b5563;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.category-tag {
  font-size: 0.7rem;
  padding: 0.25rem 0.5rem;
  border-radius: 1rem;
  font-weight: 500;
}

.category-tag.visible {
  background: #dbeafe;
  color: #1d4ed8;
}

.category-tag.hidden {
  background: #fef3c7;
  color: #b45309;
}

.examples-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

.example-card {
  background: #f3f4f6;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  padding: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s;
  min-height: 60px;
}

.example-card:not(.discovered):hover {
  background: #e5e7eb;
  border-color: #9ca3af;
}

.example-card.discovered {
  background: #d1fae5;
  border-color: #10b981;
  cursor: default;
  animation: reveal 0.3s ease;
}

@keyframes reveal {
  0% { transform: scale(0.95); opacity: 0.5; }
  100% { transform: scale(1); opacity: 1; }
}

.check {
  width: 24px;
  height: 24px;
  background: #10b981;
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  flex-shrink: 0;
}

.question {
  width: 24px;
  height: 24px;
  background: #9ca3af;
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  font-weight: bold;
  flex-shrink: 0;
}

.example-text {
  font-size: 0.8rem;
  color: #374151;
  line-height: 1.3;
}

.example-card:not(.discovered) .example-text {
  color: #6b7280;
  font-style: italic;
}

.reflection-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.reflection-panel h3 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.score-display {
  text-align: center;
  margin-bottom: 1rem;
}

.score-circle {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.5rem;
}

.score-number {
  font-size: 1.75rem;
  font-weight: 700;
  color: white;
}

.score-label {
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.8);
}

.score-message {
  font-size: 0.85rem;
  color: #4b5563;
  line-height: 1.4;
}

.reflection-questions {
  background: #f3f4f6;
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.reflection-questions h4 {
  font-size: 0.8rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.reflection-questions ul {
  list-style: none;
  padding: 0;
}

.reflection-questions li {
  font-size: 0.8rem;
  color: #6b7280;
  padding-left: 1rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.reflection-questions li::before {
  content: '→';
  position: absolute;
  left: 0;
  color: #9ca3af;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 0.75rem;
  padding: 1rem;
  font-size: 0.9rem;
  color: #374151;
  line-height: 1.5;
}

.insight-box strong {
  color: #4f46e5;
}
